import{_ as e,c as s,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"ProcessController","description":"","frontmatter":{"sidebarPos":19,"sidebarTitle":"ProcessController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/process-controller.md","filePath":"system-reference/backend/http/controllers/process-controller.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/http/controllers/process-controller.md"},a=o('<h1 id="processcontroller" tabindex="-1">ProcessController <a class="header-anchor" href="#processcontroller" aria-label="Permalink to &quot;ProcessController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/ProcessController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>Illuminate\\Routing\\Controller</code></p><p>Manages process workflow instances — retrieving their state with optional eager-loaded relationships and updating their status, reason, or processable-model fields.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="show-request-request-process-process-jsonresponse" tabindex="-1"><code>show(Request $request, Process $process): JsonResponse</code> <a class="header-anchor" href="#show-request-request-process-process-jsonresponse" aria-label="Permalink to &quot;`show(Request $request, Process $process): JsonResponse`&quot;">​</a></h3><p>Returns a process and its relationships.</p><p><strong>Request parameters</strong>:</p><table><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>with</code></td><td><code>array</code></td><td>Relationship names to eager-load</td></tr></tbody></table><p>Only relationships defined in the process model&#39;s <code>$eagerLoadable</code> property are permitted. Invalid relationships are silently ignored.</p><h3 id="update-request-request-process-process-jsonresponse" tabindex="-1"><code>update(Request $request, Process $process): JsonResponse</code> <a class="header-anchor" href="#update-request-request-process-process-jsonresponse" aria-label="Permalink to &quot;`update(Request $request, Process $process): JsonResponse`&quot;">​</a></h3><p>Updates a process. Two modes:</p><p><strong>Status/reason update</strong> — when <code>status</code> or <code>reason</code> is present:</p><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td>New process status value</td></tr><tr><td><code>reason</code></td><td>Optional reason text</td></tr></tbody></table><p><strong>Processable field update</strong> — when the request contains fields from the processable model&#39;s schema:</p><p>Fields are extracted by matching request keys against the processable model&#39;s form schema. Only schema-declared fields are written; all others are rejected.</p><p>Non-eager-loadable relations are loaded via <code>$process-&gt;load()</code> after the update so the response always contains fresh relationship data.</p><h2 id="process-model" tabindex="-1">Process Model <a class="header-anchor" href="#process-model" aria-label="Permalink to &quot;Process Model&quot;">​</a></h2><p>The <code>Process</code> model represents a state-machine instance attached to a <code>processable</code> morphable model (e.g. an Order, a Subscription). The processable model&#39;s fields can be updated directly through this controller when the process is in a state that permits editing.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>HasProcess</code> entity trait — adds process management to any model</li></ul>',20),d=[a];function n(c,l,p,i,h,u){return t(),s("div",null,d)}const q=e(r,[["render",n]]);export{b as __pageData,q as default};
